//! Differential test: the Rust parser must produce exactly what the JavaScript
//! parser produced for the same inputs (fixtures generated by
//! tests/diff/gen-ics.mjs), under several machine time zones.

use std::fs;
use std::path::PathBuf;

use blink_core::ics::{parse_tasks, ParseOptions};
use jiff::tz::TimeZone;
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    name: String,
    ics: String,
    now_ms: i64,
    keep_overdue_ms: Option<i64>,
    horizon_ms: Option<i64>,
    limit: Option<usize>,
}

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures")
}

fn read(name: &str) -> String {
    fs::read_to_string(fixtures().join(name)).unwrap_or_else(|e| panic!("{name}: {e} (run tests/diff/gen-ics.mjs)"))
}

#[test]
fn rust_matches_javascript_in_every_zone() {
    let cases: Vec<Case> = serde_json::from_str(&read("ics-cases.json")).unwrap();
    let zones: Vec<String> = serde_json::from_str(&read("ics-zones.json")).unwrap();
    assert!(cases.len() > 80, "expected the full corpus, got {}", cases.len());

    let mut failures = Vec::new();
    for zone in &zones {
        let expected: Vec<Value> =
            serde_json::from_str(&read(&format!("ics-expected.{}.json", zone.replace('/', "_")))).unwrap();
        assert_eq!(expected.len(), cases.len());
        let tz = TimeZone::get(zone).unwrap();

        for (case, want) in cases.iter().zip(&expected) {
            let mut opts = ParseOptions::new(case.now_ms);
            if let Some(v) = case.keep_overdue_ms {
                opts.keep_overdue_ms = v;
            }
            if let Some(v) = case.horizon_ms {
                opts.horizon_ms = v;
            }
            opts.limit = case.limit;

            let got = serde_json::to_value(parse_tasks(&case.ics, &opts, &tz)).unwrap();
            let want = want.get("tasks").cloned().unwrap_or(Value::Null);
            if got != want {
                failures.push(format!(
                    "[{zone}] {}\n  js:   {}\n  rust: {}",
                    case.name,
                    serde_json::to_string(&want).unwrap(),
                    serde_json::to_string(&got).unwrap()
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}
